1	import { useState } from "react";
2	import { useQuery } from "@tanstack/react-query";
3	import {
4	  BarChart,
5	  Bar,
6	  LineChart,
7	  Line,
8	  XAxis,
9	  YAxis,
10	  CartesianGrid,
11	  Tooltip,
12	  ResponsiveContainer,
13	  Cell,
14	} from "recharts";
15	import {
16	  Briefcase,
17	  Users,
18	  Clock,
19	  TrendingUp,
20	  Loader2,
21	  AlertCircle,
22	  ChevronDown,
23	} from "lucide-react";
24	import SidebarLayout from "@/components/SidebarLayout";
25	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
26	import { Skeleton } from "@/components/ui/skeleton";
27	import {
28	  Table,
29	  TableBody,
30	  TableCell,
31	  TableHead,
32	  TableHeader,
33	  TableRow,
34	} from "@/components/ui/table";
35	import {
36	  DropdownMenu,
37	  DropdownMenuContent,
38	  DropdownMenuItem,
39	  DropdownMenuTrigger,
40	} from "@/components/ui/dropdown-menu";
41	import { Button } from "@/components/ui/button";
42	import { Badge } from "@/components/ui/badge";
43	import { supabase } from "@/integrations/supabase/client";
44	import { useAuth } from "@/hooks/useAuth";
45	
46	// ─── Types ────────────────────────────────────────────────────────────────────
47	
48	interface JobRow {
49	  id: string;
50	  title: string | null;
51	  status: string | null;
52	  created_at: string;
53	  resume_count: number;
54	  avg_score: number | null;
55	}
56	
57	interface ReportsData {
58	  totalJobs: number;
59	  activeCandidates: number;
60	  avgScore: number;
61	  avgTimeToHireHours: number;
62	  funnelData: { stage: string; count: number }[];
63	  trendData: { month: string; avgHours: number }[];
64	  sourceData: { source: string; count: number }[];
65	  topJobs: JobRow[];
66	}
67	
68	const RANGE_OPTIONS = ["Last 30 days", "Last 90 days", "Last 6 months", "All time"] as const;
69	type RangeOption = (typeof RANGE_OPTIONS)[number];
70	
71	function rangeToDate(range: RangeOption): Date | null {
72	  const now = new Date();
73	  if (range === "Last 30 days") {
74	    return new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
75	  }
76	  if (range === "Last 90 days") {
77	    return new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
78	  }
79	  if (range === "Last 6 months") {
80	    return new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
81	  }
82	  return null;
83	}
84	
85	// ─── Stat card ────────────────────────────────────────────────────────────────
86	
87	interface StatCardProps {
88	  title: string;
89	  value: string;
90	  sub?: string;
91	  icon: React.ReactNode;
92	  loading?: boolean;
93	}
94	
95	function StatCard({ title, value, sub, icon, loading }: StatCardProps) {
96	  if (loading) {
97	    return (
98	      <Card className="border border-border/60 shadow-sm">
99	        <CardContent className="pt-5 pb-4 px-5">
100	          <Skeleton className="h-4 w-28 mb-3" />
101	          <Skeleton className="h-8 w-20 mb-1.5" />
102	          <Skeleton className="h-3 w-24" />
103	        </CardContent>
104	      </Card>
105	    );
106	  }
107	  return (
108	    <Card className="border border-border/60 shadow-sm">
109	      <CardContent className="pt-5 pb-4 px-5">
110	        <div className="flex items-start justify-between mb-2">
111	          <p className="text-xs font-medium text-muted-foreground">{title}</p>
112	          <span className="text-muted-foreground/60">{icon}</span>
113	        </div>
114	        <p className="text-2xl font-bold text-foreground leading-none">{value}</p>
115	        {sub && <p className="text-xs text-muted-foreground mt-1.5">{sub}</p>}
116	      </CardContent>
117	    </Card>
118	  );
119	}
120	
121	// ─── Chart skeletons ──────────────────────────────────────────────────────────
122	
123	function ChartSkeleton({ height = 220 }: { height?: number }) {
124	  return (
125	    <div className="space-y-2">
126	      <Skeleton className="h-4 w-36" />
127	      <Skeleton style={{ height }} className="w-full rounded-lg" />
128	    </div>
129	  );
130	}
131	
132	// ─── Main page ────────────────────────────────────────────────────────────────
133	
134	const Reports = () => {
135	  const { user } = useAuth();
136	  const [range, setRange] = useState<RangeOption>("Last 30 days");
137	
138	  const { data, isLoading, error } = useQuery<ReportsData>({
139	    queryKey: ["reports", user?.id, range],
140	    enabled: !!user,
141	    queryFn: async (): Promise<ReportsData> => {
142	      const since = rangeToDate(range);
143	
144	      // ── 1. Jobs in range ──
145	      let jobsQ = (supabase as any)
146	        .from("jobs")
147	        .select("id, title, status, created_at")
148	        .eq("user_id", user!.id)
149	        .order("created_at", { ascending: false });
150	
151	      if (since) {
152	        jobsQ = jobsQ.gte("created_at", since.toISOString());
153	      }
154	
155	      const { data: jobs, error: jobsErr } = await jobsQ;
156	      if (jobsErr) throw new Error(jobsErr.message);
157	
158	      const jobIds: string[] = (jobs ?? []).map((j: any) => j.id);
159	
160	      // ── 2. Resumes for those jobs ──
161	      let resumes: any[] = [];
162	      if (jobIds.length > 0) {
163	        const { data: rData, error: rErr } = await (supabase as any)
164	          .from("resumes")
165	          .select("id, job_id, status, created_at")
166	          .in("job_id", jobIds);
167	        if (rErr) throw new Error(rErr.message);
168	        resumes = rData ?? [];
169	      }
170	
171	      // ── 3. Results for scores ──
172	      let results: any[] = [];
173	      if (resumes.length > 0) {
174	        const resumeIds = resumes.map((r: any) => r.id);
175	        const { data: rData, error: rErr } = await (supabase as any)
176	          .from("results")
177	          .select("resume_id, job_id, overall_score")
178	          .in("resume_id", resumeIds);
179	        if (rErr) throw new Error(rErr.message);
180	        results = rData ?? [];
181	      }
182	
183	      // ── Derived stats ──
184	      const totalJobs = (jobs ?? []).length;
185	      const activeCandidates = resumes.filter((r: any) => r.status !== "failed").length;
186	      const scores = results.map((r: any) => r.overall_score as number).filter(Boolean);
187	      const avgScore = scores.length > 0 ? scores.reduce((a: number, b: number) => a + b, 0) / scores.length : 0;
188	
189	      // Avg time to hire: time between job created_at and last resume done status
190	      // Approximate with avg time between job creation and last resume processed
191	      let totalHours = 0;
192	      let jobsWithResumes = 0;
193	      for (const job of jobs ?? []) {
194	        const jobResumes = resumes.filter((r: any) => r.job_id === job.id && r.status === "done");
195	        if (jobResumes.length > 0) {
196	          const latest = jobResumes.reduce((max: any, r: any) =>
197	            new Date(r.created_at) > new Date(max.created_at) ? r : max
198	          );
199	          const diffMs = new Date(latest.created_at).getTime() - new Date(job.created_at).getTime();
200	          totalHours += diffMs / (1000 * 60 * 60);
201	          jobsWithResumes++;
202	        }
203	      }
204	      const avgTimeToHireHours = jobsWithResumes > 0 ? totalHours / jobsWithResumes : 0;
205	
206	      // ── Funnel data ──
207	      const pending = resumes.filter((r: any) => r.status === "pending").length;
208	      const processing = resumes.filter((r: any) => r.status === "processing").length;
209	      const done = resumes.filter((r: any) => r.status === "done").length;
210	      const failed = resumes.filter((r: any) => r.status === "failed").length;
211	
212	      const funnelData = [
213	        { stage: "Received", count: resumes.length },
214	        { stage: "Pending", count: pending },
215	        { stage: "Processing", count: processing },
216	        { stage: "Scored", count: done },
217	        { stage: "Failed", count: failed },
218	      ];
219	
220	      // ── Trend: group by month (last 6 months) ──
221	      const monthMap: Record<string, { totalHours: number; count: number }> = {};
222	      for (const job of jobs ?? []) {
223	        const jobResumes = resumes.filter((r: any) => r.job_id === job.id && r.status === "done");
224	        if (jobResumes.length === 0) continue;
225	        const latest = jobResumes.reduce((max: any, r: any) =>
226	          new Date(r.created_at) > new Date(max.created_at) ? r : max
227	        );
228	        const diffHours = (new Date(latest.created_at).getTime() - new Date(job.created_at).getTime()) / (1000 * 60 * 60);
229	        const monthKey = new Date(job.created_at).toLocaleString("default", { month: "short", year: "2-digit" });
230	        if (!monthMap[monthKey]) monthMap[monthKey] = { totalHours: 0, count: 0 };
231	        monthMap[monthKey].totalHours += diffHours;
232	        monthMap[monthKey].count++;
233	      }
234	
235	      const trendData = Object.entries(monthMap).map(([month, v]) => ({
236	        month,
237	        avgHours: Math.round(v.totalHours / v.count),
238	      }));
239	
240	      // ── Source breakdown (by job status as a proxy) ──
241	      const statusCounts: Record<string, number> = {};
242	      for (const j of jobs ?? []) {
243	        const s = j.status ?? "unknown";
244	        statusCounts[s] = (statusCounts[s] ?? 0) + 1;
245	      }
246	      const sourceData = Object.entries(statusCounts).map(([source, count]) => ({ source, count }));
247	
248	      // ── Top jobs by avg score ──
249	      const topJobs: JobRow[] = (jobs ?? [])
250	        .map((j: any) => {
251	          const jobResults = results.filter((r: any) => r.job_id === j.id);
252	          const jobScores = jobResults.map((r: any) => r.overall_score as number).filter(Boolean);
253	          const avgJobScore = jobScores.length > 0
254	            ? jobScores.reduce((a: number, b: number) => a + b, 0) / jobScores.length
255	            : null;
256	          return {
257	            id: j.id,
258	            title: j.title,
259	            status: j.status,
260	            created_at: j.created_at,
261	            resume_count: resumes.filter((r: any) => r.job_id === j.id).length,
262	            avg_score: avgJobScore ? Math.round(avgJobScore) : null,
263	          } as JobRow;
264	        })
265	        .sort((a: JobRow, b: JobRow) => (b.avg_score ?? 0) - (a.avg_score ?? 0))
266	        .slice(0, 10);
267	
268	      return {
269	        totalJobs,
270	        activeCandidates,
271	        avgScore: Math.round(avgScore),
272	        avgTimeToHireHours: Math.round(avgTimeToHireHours * 10) / 10,
273	        funnelData,
274	        trendData,
275	        sourceData,
276	        topJobs,
277	      };
278	    },
279	  });
280	
281	  const funnelColors = ["#6366f1", "#8b5cf6", "#a78bfa", "#c4b5fd", "#ef4444"];
282	
283	  return (
284	    <SidebarLayout>
285	      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
286	        {/* Header */}
287	        <div className="flex items-start justify-between mb-6">
288	          <div>
289	            <h1 className="text-2xl font-bold text-foreground mb-0.5">Reports</h1>
290	            <p className="text-sm text-muted-foreground">Hiring analytics for your account.</p>
291	          </div>
292	
293	          {/* Range filter */}
294	          <DropdownMenu>
295	            <DropdownMenuTrigger asChild>
296	              <Button variant="outline" size="sm" className="gap-1.5 text-xs h-8">
297	                {range}
298	                <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />
299	              </Button>
300	            </DropdownMenuTrigger>
301	            <DropdownMenuContent align="end" className="text-sm">
302	              {RANGE_OPTIONS.map((opt) => (
303	                <DropdownMenuItem key={opt} onClick={() => setRange(opt)} className="text-xs">
304	                  {opt}
305	                </DropdownMenuItem>
306	              ))}
307	            </DropdownMenuContent>
308	          </DropdownMenu>
309	        </div>
310	
311	        {/* Error state */}
312	        {error && (
313	          <Card className="border-destructive/40 mb-6">
314	            <CardContent className="py-8 flex flex-col items-center gap-2 text-center">
315	              <AlertCircle className="h-7 w-7 text-destructive" />
316	              <p className="text-sm text-muted-foreground">Failed to load report data. Please refresh.</p>
317	            </CardContent>
318	          </Card>
319	        )}
320	
321	        {/* ── Stat cards ── */}
322	        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
323	          <StatCard
324	            title="Total Jobs"
325	            value={isLoading ? "—" : String(data?.totalJobs ?? 0)}
326	            sub="In selected period"
327	            icon={<Briefcase className="h-4 w-4" />}
328	            loading={isLoading}
329	          />
330	          <StatCard
331	            title="Active Candidates"
332	            value={isLoading ? "—" : String(data?.activeCandidates ?? 0)}
333	            sub="Resumes uploaded"
334	            icon={<Users className="h-4 w-4" />}
335	            loading={isLoading}
336	          />
337	          <StatCard
338	            title="Avg Time-to-Hire"
339	            value={isLoading ? "—" : `${data?.avgTimeToHireHours ?? 0}h`}
340	            sub="From job to scored"
341	            icon={<Clock className="h-4 w-4" />}
342	            loading={isLoading}
343	          />
344	          <StatCard
345	            title="Avg Score"
346	            value={isLoading ? "—" : `${data?.avgScore ?? 0}%`}
347	            sub="Across all candidates"
348	            icon={<TrendingUp className="h-4 w-4" />}
349	            loading={isLoading}
350	          />
351	        </div>
352	
353	        {/* ── Charts row ── */}
354	        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
355	          {/* Hiring funnel */}
356	          <Card className="border border-border/60 shadow-sm">
357	            <CardHeader className="pb-2 px-5 pt-4">
358	              <CardTitle className="text-sm font-semibold">Hiring Funnel</CardTitle>
359	              <CardDescription className="text-xs">Candidates by pipeline stage</CardDescription>
360	            </CardHeader>
361	            <CardContent className="px-4 pb-4">
362	              {isLoading ? (
363	                <ChartSkeleton height={200} />
364	              ) : (
365	                <ResponsiveContainer width="100%" height={200}>
366	                  <BarChart data={data?.funnelData ?? []} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
367	                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
368	                    <XAxis
369	                      dataKey="stage"
370	                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
371	                      axisLine={false}
372	                      tickLine={false}
373	                    />
374	                    <YAxis
375	                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
376	                      axisLine={false}
377	                      tickLine={false}
378	                    />
379	                    <Tooltip
380	                      contentStyle={{
381	                        backgroundColor: "hsl(var(--popover))",
382	                        border: "1px solid hsl(var(--border))",
383	                        borderRadius: 8,
384	                        fontSize: 12,
385	                      }}
386	                      cursor={{ fill: "hsl(var(--muted))" }}
387	                    />
388	                    <Bar dataKey="count" radius={[4, 4, 0, 0]}>
389	                      {(data?.funnelData ?? []).map((_: unknown, idx: number) => (
390	                        <Cell key={idx} fill={funnelColors[idx % funnelColors.length]} />
391	                      ))}
392	                    </Bar>
393	                  </BarChart>
394	                </ResponsiveContainer>
395	              )}
396	            </CardContent>
397	          </Card>
398	
399	          {/* Time-to-hire trend */}
400	          <Card className="border border-border/60 shadow-sm">
401	            <CardHeader className="pb-2 px-5 pt-4">
402	              <CardTitle className="text-sm font-semibold">Time-to-Hire Trend</CardTitle>
403	              <CardDescription className="text-xs">Avg hours per month</CardDescription>
404	            </CardHeader>
405	            <CardContent className="px-4 pb-4">
406	              {isLoading ? (
407	                <ChartSkeleton height={200} />
408	              ) : (data?.trendData ?? []).length === 0 ? (
409	                <div className="flex flex-col items-center justify-center h-[200px] text-center gap-2">
410	                  <Clock className="h-7 w-7 text-muted-foreground/40" />
411	                  <p className="text-xs text-muted-foreground">Not enough data yet</p>
412	                </div>
413	              ) : (
414	                <ResponsiveContainer width="100%" height={200}>
415	                  <LineChart data={data?.trendData ?? []} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
416	                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
417	                    <XAxis
418	                      dataKey="month"
419	                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
420	                      axisLine={false}
421	                      tickLine={false}
422	                    />
423	                    <YAxis
424	                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
425	                      axisLine={false}
426	                      tickLine={false}
427	                    />
428	                    <Tooltip
429	                      contentStyle={{
430	                        backgroundColor: "hsl(var(--popover))",
431	                        border: "1px solid hsl(var(--border))",
432	                        borderRadius: 8,
433	                        fontSize: 12,
434	                      }}
435	                    />
436	                    <Line
437	                      type="monotone"
438	                      dataKey="avgHours"
439	                      stroke="#6366f1"
440	                      strokeWidth={2}
441	                      dot={{ r: 3, fill: "#6366f1" }}
442	                      activeDot={{ r: 5 }}
443	                    />
444	                  </LineChart>
445	                </ResponsiveContainer>
446	              )}
447	            </CardContent>
448	          </Card>
449	        </div>
450	
451	        {/* ── Source breakdown ── */}
452	        <Card className="border border-border/60 shadow-sm mb-6">
453	          <CardHeader className="pb-2 px-5 pt-4">
454	            <CardTitle className="text-sm font-semibold">Job Status Breakdown</CardTitle>
455	            <CardDescription className="text-xs">Count of jobs by their current status</CardDescription>
456	          </CardHeader>
457	          <CardContent className="px-4 pb-4">
458	            {isLoading ? (
459	              <ChartSkeleton height={160} />
460	            ) : (data?.sourceData ?? []).length === 0 ? (
461	              <div className="flex flex-col items-center justify-center h-[160px] text-center gap-2">
462	                <Briefcase className="h-7 w-7 text-muted-foreground/40" />
463	                <p className="text-xs text-muted-foreground">No job data in this period</p>
464	              </div>
465	            ) : (
466	              <ResponsiveContainer width="100%" height={160}>
467	                <BarChart
468	                  data={data?.sourceData ?? []}
469	                  layout="vertical"
470	                  margin={{ top: 0, right: 20, left: 10, bottom: 0 }}
471	                >
472	                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" horizontal={false} />
473	                  <XAxis
474	                    type="number"
475	                    tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
476	                    axisLine={false}
477	                    tickLine={false}
478	                  />
479	                  <YAxis
480	                    type="category"
481	                    dataKey="source"
482	                    tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
483	                    axisLine={false}
484	                    tickLine={false}
485	                    width={80}
486	                  />
487	                  <Tooltip
488	                    contentStyle={{
489	                      backgroundColor: "hsl(var(--popover))",
490	                      border: "1px solid hsl(var(--border))",
491	                      borderRadius: 8,
492	                      fontSize: 12,
493	                    }}
494	                    cursor={{ fill: "hsl(var(--muted))" }}
495	                  />
496	                  <Bar dataKey="count" fill="#6366f1" radius={[0, 4, 4, 0]} />
497	                </BarChart>
498	              </ResponsiveContainer>
499	            )}
500	          </CardContent>
501	        </Card>
502	
503	        {/* ── Top jobs table ── */}
504	        <Card className="border border-border/60 shadow-sm">
505	          <CardHeader className="px-5 pt-4 pb-2">
506	            <CardTitle className="text-sm font-semibold">Top Jobs by Score</CardTitle>
507	            <CardDescription className="text-xs">Your highest-performing job postings</CardDescription>
508	          </CardHeader>
509	          <CardContent className="p-0">
510	            {isLoading ? (
511	              <div className="p-5 space-y-3">
512	                {[1, 2, 3, 4].map((i) => (
513	                  <div key={i} className="flex items-center gap-3">
514	                    <Skeleton className="h-4 flex-1" />
515	                    <Skeleton className="h-4 w-16" />
516	                    <Skeleton className="h-4 w-12" />
517	                    <Skeleton className="h-4 w-10" />
518	                  </div>
519	                ))}
520	              </div>
521	            ) : (data?.topJobs ?? []).length === 0 ? (
522	              <div className="flex flex-col items-center justify-center py-12 text-center gap-2">
523	                <Briefcase className="h-7 w-7 text-muted-foreground/40" />
524	                <p className="text-xs text-muted-foreground">No jobs in this period</p>
525	              </div>
526	            ) : (
527	              <Table>
528	                <TableHeader>
529	                  <TableRow>
530	                    <TableHead className="text-xs pl-5">Job Title</TableHead>
531	                    <TableHead className="text-xs">Status</TableHead>
532	                    <TableHead className="text-xs">Candidates</TableHead>
533	                    <TableHead className="text-xs">Avg Score</TableHead>
534	                    <TableHead className="text-xs pr-5">Created</TableHead>
535	                  </TableRow>
536	                </TableHeader>
537	                <TableBody>
538	                  {(data?.topJobs ?? []).map((job: JobRow) => (
539	                    <TableRow key={job.id}>
540	                      <TableCell className="text-sm font-medium pl-5 max-w-[200px] truncate">
541	                        {job.title ?? "Untitled Job"}
542	                      </TableCell>
543	                      <TableCell>
544	                        <Badge
545	                          variant="outline"
546	                          className={
547	                            job.status === "completed"
548	                              ? "text-green-600 border-green-500/40 text-[10px]"
549	                              : job.status === "processing"
550	                              ? "text-blue-600 border-blue-500/40 text-[10px]"
551	                              : job.status === "failed"
552	                              ? "text-destructive border-destructive/40 text-[10px]"
553	                              : "text-muted-foreground text-[10px]"
554	                          }
555	                        >
556	                          {job.status ?? "pending"}
557	                        </Badge>
558	                      </TableCell>
559	                      <TableCell className="text-sm text-muted-foreground">{job.resume_count}</TableCell>
560	                      <TableCell className="text-sm font-semibold">
561	                        {job.avg_score != null ? `${job.avg_score}%` : <span className="text-muted-foreground font-normal">—</span>}
562	                      </TableCell>
