import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

const STALE_TIME = 5 * 60 * 1000; // 5 minutes

// ─── Types ────────────────────────────────────────────────────────────────────

export interface TimeToHireRow {
  job_id: string;
  title: string | null;
  job_created: string;
  first_hire_at: string | null;
  days_to_hire: number | null;
}

export interface StageConversionRow {
  job_id: string;
  stage: string;
  count: number;
}

export interface ScoreDistributionRow {
  bucket: string;
  count: number;
}

export interface DailyActivityRow {
  activity_date: string;
  resumes_processed: number;
  jobs_active: number;
}

export interface TopJobRow {
  job_id: string;
  title: string | null;
  candidate_count: number;
  avg_score: number;
  top_score: number;
}

export interface ProductivityStats {
  total_jobs: number;
  total_candidates: number;
  total_credits_used: number;
  avg_candidates_per_job: number;
  jobs_last_30_days: number;
  candidates_last_30_days: number;
}

// Aggregated funnel: stage → total across all jobs for this user
export interface FunnelItem {
  stage: string;
  count: number;
  label: string;
}

// ─── Hooks ────────────────────────────────────────────────────────────────────

export function useTimeToHire() {
  const { user } = useAuth();
  return useQuery<TimeToHireRow[]>({
    queryKey: ["analytics_time_to_hire", user?.id],
    enabled: !!user,
    staleTime: STALE_TIME,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("v_time_to_hire")
        .select("job_id, title, job_created, first_hire_at, days_to_hire")
        .eq("user_id", user!.id)
        .not("days_to_hire", "is", null);
      if (error) throw new Error(error.message);
      return (data ?? []) as TimeToHireRow[];
    },
  });
}

export function useStageConversion() {
  const { user } = useAuth();
  return useQuery<FunnelItem[]>({
    queryKey: ["analytics_stage_conversion", user?.id],
    enabled: !!user,
    staleTime: STALE_TIME,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("v_stage_conversion")
        .select("stage, count")
        .eq("user_id", user!.id);
      if (error) throw new Error(error.message);

      const rows = (data ?? []) as StageConversionRow[];

      // Aggregate counts across all jobs per stage
      const stageTotals: Record<string, number> = {};
      for (const row of rows) {
        stageTotals[row.stage] = (stageTotals[row.stage] ?? 0) + row.count;
      }

      const STAGE_ORDER = [
        { key: "applied",   label: "Applied" },
        { key: "screened",  label: "Screened" },
        { key: "interview", label: "Interview" },
        { key: "offer",     label: "Offer" },
        { key: "hired",     label: "Hired" },
      ];

      return STAGE_ORDER.map(({ key, label }) => ({
        stage: key,
        label,
        count: stageTotals[key] ?? 0,
      }));
    },
  });
}

export function useScoreDistribution() {
  const { user } = useAuth();
  return useQuery<ScoreDistributionRow[]>({
    queryKey: ["analytics_score_distribution", user?.id],
    enabled: !!user,
    staleTime: STALE_TIME,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("v_score_distribution")
        .select("bucket, count")
        .eq("user_id", user!.id)
        .order("bucket");
      if (error) throw new Error(error.message);

      // Ensure all 10 buckets are present even if count=0
      const BUCKETS = [
        "0-9","10-19","20-29","30-39","40-49",
        "50-59","60-69","70-79","80-89","90-100",
      ];
      const byBucket: Record<string, number> = {};
      for (const row of (data ?? []) as ScoreDistributionRow[]) {
        byBucket[row.bucket] = row.count;
      }
      return BUCKETS.map((b) => ({ bucket: b, count: byBucket[b] ?? 0 }));
    },
  });
}

export function useDailyActivity() {
  const { user } = useAuth();
  return useQuery<DailyActivityRow[]>({
    queryKey: ["analytics_daily_activity", user?.id],
    enabled: !!user,
    staleTime: STALE_TIME,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("v_daily_activity")
        .select("activity_date, resumes_processed, jobs_active")
        .eq("user_id", user!.id)
        .order("activity_date");
      if (error) throw new Error(error.message);
      return (data ?? []) as DailyActivityRow[];
    },
  });
}

export function useTopJobs() {
  const { user } = useAuth();
  return useQuery<TopJobRow[]>({
    queryKey: ["analytics_top_jobs", user?.id],
    enabled: !!user,
    staleTime: STALE_TIME,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("v_top_jobs")
        .select("job_id, title, candidate_count, avg_score, top_score")
        .eq("user_id", user!.id)
        .order("avg_score", { ascending: false })
        .limit(10);
      if (error) throw new Error(error.message);
      return (data ?? []) as TopJobRow[];
    },
  });
}

export function useProductivityStats() {
  const { user } = useAuth();
  return useQuery<ProductivityStats>({
    queryKey: ["analytics_productivity", user?.id],
    enabled: !!user,
    staleTime: STALE_TIME,
    queryFn: async () => {
      const { data, error } = await (supabase as any).rpc("user_productivity_stats", {
        p_user_id: user!.id,
      });
      if (error) throw new Error(error.message);
      // RPC returns an array with one row
      const row = Array.isArray(data) ? data[0] : data;
      return (row ?? {
        total_jobs: 0,
        total_candidates: 0,
        total_credits_used: 0,
        avg_candidates_per_job: 0,
        jobs_last_30_days: 0,
        candidates_last_30_days: 0,
      }) as ProductivityStats;
    },
  });
}

import { Clock, TrendingDown, TrendingUp, Minus } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useTimeToHire } from "@/hooks/useAnalytics";

function AnalyticsEmptyState({ icon, message }: { icon: React.ReactNode; message: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-8 gap-2 text-center">
      <div className="text-muted-foreground/40">{icon}</div>
      <p className="text-xs text-muted-foreground max-w-[200px]">{message}</p>
    </div>
  );
}

export function TimeToHireCard() {
  const { data, isLoading, error } = useTimeToHire();

  const rows = data ?? [];
  const avg =
    rows.length > 0
      ? Math.round(rows.reduce((sum, r) => sum + (r.days_to_hire ?? 0), 0) / rows.length)
      : null;

  // Compare last 5 vs previous 5 for trend
  let trend: "up" | "down" | "neutral" = "neutral";
  if (rows.length >= 4) {
    const half = Math.floor(rows.length / 2);
    const recentAvg =
      rows.slice(-half).reduce((s, r) => s + (r.days_to_hire ?? 0), 0) / half;
    const prevAvg =
      rows.slice(0, half).reduce((s, r) => s + (r.days_to_hire ?? 0), 0) / half;
    if (recentAvg < prevAvg - 0.5) trend = "down"; // faster = good
    else if (recentAvg > prevAvg + 0.5) trend = "up"; // slower = bad
  }

  const TrendIcon =
    trend === "down" ? TrendingDown : trend === "up" ? TrendingUp : Minus;
  const trendColor =
    trend === "down"
      ? "text-green-600"
      : trend === "up"
      ? "text-red-500"
      : "text-muted-foreground";
  const trendLabel =
    trend === "down"
      ? "Improving (faster hires)"
      : trend === "up"
      ? "Slowing down"
      : "Stable";

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardHeader className="pb-2 px-5 pt-4">
        <CardTitle className="text-sm font-semibold">Time to Hire</CardTitle>
        <CardDescription className="text-xs">
          Avg days from job creation to first hire
        </CardDescription>
      </CardHeader>
      <CardContent className="px-5 pb-5">
        {isLoading ? (
          <div className="space-y-2">
            <Skeleton className="h-10 w-24" />
            <Skeleton className="h-3 w-32" />
          </div>
        ) : error ? (
          <AnalyticsEmptyState
            icon={<Clock className="h-8 w-8" />}
            message="Could not load hiring data"
          />
        ) : avg === null ? (
          <AnalyticsEmptyState
            icon={<Clock className="h-8 w-8" />}
            message="No hires tracked yet. Move candidates to the Hired stage to see this metric."
          />
        ) : (
          <div className="space-y-3">
            <div className="flex items-end gap-2">
              <span className="text-4xl font-bold text-foreground leading-none">
                {avg}
              </span>
              <span className="text-sm text-muted-foreground mb-0.5">days</span>
            </div>
            <div className={`flex items-center gap-1.5 text-xs ${trendColor}`}>
              <TrendIcon className="h-3.5 w-3.5" />
              <span>{trendLabel}</span>
            </div>
            <p className="text-xs text-muted-foreground">
              Based on {rows.length} completed hire{rows.length !== 1 ? "s" : ""}
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Users } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from "recharts";
import { useStageConversion } from "@/hooks/useAnalytics";

const STAGE_COLORS: Record<string, string> = {
  applied:   "#6366f1",
  screened:  "#8b5cf6",
  interview: "#a78bfa",
  offer:     "#c4b5fd",
  hired:     "#22c55e",
};

function ConversionRate({ from, to }: { from: number; to: number }) {
  if (from === 0) return null;
  const rate = Math.round((to / from) * 100);
  return (
    <span className="text-[10px] text-muted-foreground ml-1">({rate}%)</span>
  );
}

export function StageFunnel() {
  const { data, isLoading, error } = useStageConversion();
  const rows = data ?? [];
  const totalApplied = rows[0]?.count ?? 0;

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardHeader className="pb-2 px-5 pt-4">
        <CardTitle className="text-sm font-semibold">Stage Conversion Funnel</CardTitle>
        <CardDescription className="text-xs">
          Candidates at each pipeline stage across all jobs
        </CardDescription>
      </CardHeader>
      <CardContent className="px-4 pb-4">
        {isLoading ? (
          <div className="space-y-2">
            <Skeleton className="h-4 w-36" />
            <Skeleton className="h-[200px] w-full rounded-lg" />
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center h-[200px] gap-2">
            <Users className="h-7 w-7 text-muted-foreground/40" />
            <p className="text-xs text-muted-foreground">Could not load funnel data</p>
          </div>
        ) : totalApplied === 0 ? (
          <div className="flex flex-col items-center justify-center h-[200px] gap-2 text-center">
            <Users className="h-7 w-7 text-muted-foreground/40" />
            <p className="text-xs text-muted-foreground max-w-[200px]">
              Start moving candidates through pipeline stages to see conversion rates here.
            </p>
          </div>
        ) : (
          <>
            <ResponsiveContainer width="100%" height={200}>
              <BarChart
                data={rows}
                margin={{ top: 4, right: 8, left: -20, bottom: 0 }}
              >
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="hsl(var(--border))"
                  vertical={false}
                />
                <XAxis
                  dataKey="label"
                  tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                  axisLine={false}
                  tickLine={false}
                />
                <YAxis
                  tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                  axisLine={false}
                  tickLine={false}
                  allowDecimals={false}
                />
                <Tooltip
                  contentStyle={{
                    backgroundColor: "hsl(var(--popover))",
                    border: "1px solid hsl(var(--border))",
                    borderRadius: 8,
                    fontSize: 12,
                  }}
                  cursor={{ fill: "hsl(var(--muted))" }}
                  formatter={(value: number, _name: string, props: { payload?: { label?: string } }) => [
                    value,
                    props?.payload?.label ?? "Candidates",
                  ]}
                />
                <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                  {rows.map((row) => (
                    <Cell
                      key={row.stage}
                      fill={STAGE_COLORS[row.stage] ?? "#6366f1"}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>

            {/* Conversion rates below chart */}
            <div className="flex items-center justify-between mt-3 px-1">
              {rows.map((row, idx) => (
                <div key={row.stage} className="flex flex-col items-center text-center">
                  <span className="text-xs font-medium text-foreground">{row.count}</span>
                  {idx > 0 && (
                    <ConversionRate from={rows[idx - 1].count} to={row.count} />
                  )}
                  {idx === 0 && (
                    <span className="text-[10px] text-muted-foreground">total</span>
                  )}
                </div>
              ))}
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

