import { CalendarDays } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useDailyActivity } from "@/hooks/useAnalytics";
import type { DailyActivityRow } from "@/hooks/useAnalytics";

// ─── Build 90-day grid ────────────────────────────────────────────────────────

function buildGrid(rows: DailyActivityRow[]) {
  const byDate: Record<string, number> = {};
  for (const row of rows) {
    byDate[row.activity_date.slice(0, 10)] = row.resumes_processed;
  }

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const days: { date: string; count: number; weekday: number }[] = [];
  for (let i = 89; i >= 0; i--) {
    const d = new Date(today.getTime() - i * 86400000);
    const key = d.toISOString().slice(0, 10);
    days.push({
      date: key,
      count: byDate[key] ?? 0,
      weekday: d.getDay(), // 0=Sun
    });
  }
  return days;
}

// ─── Intensity colour ─────────────────────────────────────────────────────────

function intensityClass(count: number, max: number): string {
  if (count === 0) return "bg-muted/40 border border-border/30";
  const ratio = count / Math.max(max, 1);
  if (ratio < 0.25) return "bg-indigo-200 dark:bg-indigo-900/60";
  if (ratio < 0.5)  return "bg-indigo-400 dark:bg-indigo-700";
  if (ratio < 0.75) return "bg-indigo-500 dark:bg-indigo-600";
  return "bg-indigo-600 dark:bg-indigo-500";
}

// ─── Tooltip (pure div, no lib) ───────────────────────────────────────────────

interface CellProps {
  date: string;
  count: number;
  max: number;
}

function HeatCell({ date, count, max }: CellProps) {
  const label = new Date(date + "T00:00:00").toLocaleDateString("default", {
    month: "short",
    day: "numeric",
  });
  const title =
    count === 0
      ? `${label}: no activity`
      : `${label}: ${count} candidate${count !== 1 ? "s" : ""} processed`;

  return (
    <div
      className={`w-3 h-3 rounded-[2px] cursor-default ${intensityClass(count, max)}`}
      title={title}
    />
  );
}

// ─── Week-day labels ──────────────────────────────────────────────────────────
const DAY_LABELS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

// ─── Main component ───────────────────────────────────────────────────────────

export function ActivityHeatmap() {
  const { data, isLoading, error } = useDailyActivity();

  const rows = data ?? [];
  const grid = buildGrid(rows);
  const maxCount = Math.max(...grid.map((d) => d.count), 1);
  const totalProcessed = rows.reduce((s, r) => s + r.resumes_processed, 0);

  // Group into weeks (columns of 7 days, starting from first day)
  const weeks: typeof grid[number][][] = [];
  let week: typeof grid[number][] = [];

  // Pad start so week starts on Sunday
  const firstWeekday = grid[0]?.weekday ?? 0;
  for (let i = 0; i < firstWeekday; i++) {
    week.push({ date: "", count: -1, weekday: i }); // empty padding cells
  }

  for (const day of grid) {
    week.push(day);
    if (week.length === 7) {
      weeks.push(week);
      week = [];
    }
  }
  if (week.length > 0) {
    while (week.length < 7) week.push({ date: "", count: -1, weekday: week.length });
    weeks.push(week);
  }

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardHeader className="pb-2 px-5 pt-4">
        <CardTitle className="text-sm font-semibold">Activity Heatmap</CardTitle>
        <CardDescription className="text-xs">
          {totalProcessed > 0
            ? `${totalProcessed} candidates processed in the last 90 days`
            : "Candidate processing activity over the last 90 days"}
        </CardDescription>
      </CardHeader>
      <CardContent className="px-5 pb-5">
        {isLoading ? (
          <Skeleton className="h-[100px] w-full rounded-lg" />
        ) : error ? (
          <div className="flex flex-col items-center justify-center h-[100px] gap-2">
            <CalendarDays className="h-7 w-7 text-muted-foreground/40" />
            <p className="text-xs text-muted-foreground">Could not load activity data</p>
          </div>
        ) : totalProcessed === 0 ? (
          <div className="flex flex-col items-center justify-center py-6 gap-2 text-center">
            <CalendarDays className="h-7 w-7 text-muted-foreground/40" />
            <p className="text-xs text-muted-foreground max-w-[220px]">
              Start creating jobs and ranking candidates to see your hiring activity here.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <div className="inline-flex gap-0">
              {/* Day-of-week labels */}
              <div className="flex flex-col gap-[2px] mr-1.5 pt-[18px]">
                {DAY_LABELS.map((d) => (
                  <span
                    key={d}
                    className="text-[9px] text-muted-foreground leading-none h-3 flex items-center"
                  >
                    {d}
                  </span>
                ))}
              </div>

              {/* Grid columns = weeks */}
              <div className="flex flex-col">
                {/* Month labels row */}
                <div className="flex gap-[2px] mb-1">
                  {weeks.map((week, wi) => {
                    // Show month label when month changes
                    const firstReal = week.find((d) => d.date !== "");
                    if (!firstReal) return <div key={wi} className="w-3" />;
                    const isFirstOfMonth = firstReal.date.slice(8, 10) <= "07";
                    const monthLabel = isFirstOfMonth
                      ? new Date(firstReal.date + "T00:00:00").toLocaleString("default", { month: "short" })
                      : "";
                    return (
                      <div key={wi} className="w-3 text-[9px] text-muted-foreground leading-none">
                        {monthLabel}
                      </div>
                    );
                  })}
                </div>

                {/* Day rows */}
                {DAY_LABELS.map((_, dayIdx) => (
                  <div key={dayIdx} className="flex gap-[2px] mb-[2px]">
                    {weeks.map((week, wi) => {
                      const day = week[dayIdx];
                      if (!day || day.count === -1 || !day.date) {
                        return <div key={wi} className="w-3 h-3" />;
                      }
                      return (
                        <HeatCell
                          key={wi}
                          date={day.date}
                          count={day.count}
                          max={maxCount}
                        />
                      );
                    })}
                  </div>
                ))}
              </div>
            </div>

            {/* Legend */}
            <div className="flex items-center gap-1.5 mt-3">
              <span className="text-[10px] text-muted-foreground">Less</span>
              {[0, 0.2, 0.5, 0.75, 1].map((ratio, i) => (
                <div
                  key={i}
                  className={`w-3 h-3 rounded-[2px] ${intensityClass(Math.round(ratio * maxCount), maxCount)}`}
                />
              ))}
              <span className="text-[10px] text-muted-foreground">More</span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { Briefcase } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
