function ScoreBadge({ score }: { score: number }) {
  const colorClass =
    score >= 80
      ? "text-green-700 border-green-500/40 bg-green-50 dark:bg-green-950/30 dark:text-green-400"
      : score >= 60
      ? "text-indigo-700 border-indigo-500/40 bg-indigo-50 dark:bg-indigo-950/30 dark:text-indigo-400"
      : score >= 40
      ? "text-amber-700 border-amber-500/40 bg-amber-50 dark:bg-amber-950/30 dark:text-amber-400"
      : "text-muted-foreground";

  return (
    <Badge variant="outline" className={`text-[10px] font-semibold ${colorClass}`}>
      {score}%
    </Badge>
  );
}

