import {
  Briefcase,
  Users,
  Coins,
  BarChart2,
  Clock,
  Zap,
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useProductivityStats } from "@/hooks/useAnalytics";
import type { ProductivityStats } from "@/hooks/useAnalytics";

interface StatTileProps {
  label: string;
  value: string | number;
  sub: string;
  icon: React.ReactNode;
  loading: boolean;
  accent?: string;
}

function StatTile({ label, value, sub, icon, loading, accent = "text-muted-foreground/60" }: StatTileProps) {
  if (loading) {
    return (
      <Card className="border border-border/60 shadow-sm">
        <CardContent className="pt-4 pb-3 px-4">
          <Skeleton className="h-3 w-24 mb-3" />
          <Skeleton className="h-7 w-16 mb-1" />
          <Skeleton className="h-2.5 w-20" />
        </CardContent>
      </Card>
    );
  }
  return (
    <Card className="border border-border/60 shadow-sm">
      <CardContent className="pt-4 pb-3 px-4">
        <div className="flex items-start justify-between mb-1.5">
          <p className="text-xs font-medium text-muted-foreground">{label}</p>
          <span className={accent}>{icon}</span>
        </div>
        <p className="text-2xl font-bold text-foreground leading-none">{value}</p>
        <p className="text-[10px] text-muted-foreground mt-1">{sub}</p>
      </CardContent>
    </Card>
  );
}

function buildTiles(stats: ProductivityStats | undefined, loading: boolean) {
  return [
    {
      label: "Total Jobs",
      value: stats?.total_jobs ?? 0,
      sub: "All time",
      icon: <Briefcase className="h-4 w-4" />,
    },
    {
      label: "Total Candidates",
      value: stats?.total_candidates ?? 0,
      sub: "All time",
      icon: <Users className="h-4 w-4" />,
    },
    {
      label: "Credits Used",
      value: stats?.total_credits_used ?? 0,
      sub: "All time",
      icon: <Coins className="h-4 w-4" />,
    },
    {
      label: "Avg Candidates / Job",
      value: stats?.avg_candidates_per_job ?? 0,
      sub: "Per posting",
      icon: <BarChart2 className="h-4 w-4" />,
    },
    {
      label: "Jobs (Last 30 days)",
      value: stats?.jobs_last_30_days ?? 0,
      sub: "Recent activity",
      icon: <Clock className="h-4 w-4" />,
    },
    {
      label: "Candidates (Last 30 days)",
      value: stats?.candidates_last_30_days ?? 0,
      sub: "Recent activity",
      icon: <Zap className="h-4 w-4" />,
    },
  ].map((tile) => ({ ...tile, loading }));
}

export function ProductivityGrid() {
  const { data, isLoading } = useProductivityStats();
  const tiles = buildTiles(data, isLoading);

  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
      {tiles.map((tile) => (
        <StatTile
          key={tile.label}
          label={tile.label}
          value={tile.value}
          sub={tile.sub}
          icon={tile.icon}
          loading={tile.loading}
        />
      ))}
    </div>
  );
}

